package com.nthexperience.desktop;

import android.Manifest;import android.accessibilityservice.AccessibilityServiceInfo;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.location.*;import android.os.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Real Android permission dialogs and mock-provider callbacks. No physical/device-user location is used. */
public final class EightLocationSmoke extends Instrumentation {
    MainActivity home;View root;DesktopStore store;EightMaps maps;LocationManager manager;final List<String> mocks=new ArrayList<>();String choice="pre-Android-12 fine grant";
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();boolean passed=false;try{
        store=new DesktopStore(getTargetContext());EightDefaults.initialize(store);store.prefs.edit().putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).commit();getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();waitForIdleSync();AccessibilityServiceInfo info=getUiAutomation().getServiceInfo();info.flags|=AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS;getUiAutomation().setServiceInfo(info);ui(()->home.openEightTile("@maps"));maps=EightSmoke.find(root,EightMaps.class);manager=getTargetContext().getSystemService(LocationManager.class);check(manager!=null,"Location service exists");
        shell("cmd location set-location-enabled true");shell("appops set "+getTargetContext().getPackageName()+" android:mock_location allow");
        ui(()->{for(String provider:new String[]{LocationManager.GPS_PROVIDER,"fused",LocationManager.NETWORK_PROVIDER}){manager.addTestProvider(provider,false,false,false,false,false,false,false,Criteria.POWER_LOW,provider.equals(LocationManager.GPS_PROVIDER)?Criteria.ACCURACY_FINE:Criteria.ACCURACY_COARSE);manager.setTestProviderEnabled(provider,true);mocks.add(provider);}});
        // First denial leaves coordinate search fully usable.
        ui(maps::locate);awaitNode("permission_deny_button","Don't allow");recordTree("eight-location-initial-permission-tree.txt");if(Build.VERSION.SDK_INT>=31){check(node("permission_location_accuracy_radio_fine","Precise")!=null&&node("permission_location_accuracy_radio_coarse","Approximate")!=null,"Real Android dialog offers both accuracy choices");}tapSystem("permission_deny_button","Don't allow");await(()->!maps.permitted()&&maps.locationStatus.getText().toString().contains("Location access is off"),"Denied location returns to usable Maps");ui(()->{maps.search("40.5,-74.2");check(maps.lat==40.5&&maps.lon==-74.2,"Denied location still supports coordinate search");});
        ui(maps::locate);awaitNode("permission_allow_foreground_only_button","While using the app");if(Build.VERSION.SDK_INT>=31)tapSystem("permission_location_accuracy_radio_coarse","Approximate");tapSystem("permission_allow_foreground_only_button","While using the app");await(maps::permitted,"Actual Android location permission delivered");waitForIdleSync();
        if(Build.VERSION.SDK_INT>=31){choice="real Approximate grant and upgrade to Precise";check(!maps.precise(),"Approximate choice does not grant Fine");await(()->maps.locating&&!maps.preciseSearch,"Coarse-only permission callback starts approximate lookup");ui(()->manager.setTestProviderLocation("fused",fix("fused",40.5,-74.2,1800)));await(()->maps.lastFix!=null&&!maps.locating,"Actual coarse provider callback produces approximate fix");check(maps.locationStatus.getText().toString().contains("Approximate access"),"Approximate fix remains explicitly labeled");shot("eight-location-approximate");ui(maps::accuracyOptions);check(maps.accuracyDialog.isShowing(),"Accuracy options are visible");ui(()->maps.accuracyDialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick());awaitNode("permission_allow_foreground_only_button","Change to precise location");recordTree("eight-location-upgrade-permission-tree.txt");tapSystem("permission_allow_foreground_only_button","Change to precise location");await(maps::precise,"Actual Android upgrade grants Fine");}else await(maps::precise,"Android 11 grants Fine from joint request");
        ui(maps::stopLocation);
        Location stale=fix(LocationManager.GPS_PROVIDER,1,2,3);stale.setTime(System.currentTimeMillis()-300000);stale.setElapsedRealtimeNanos(Math.max(1,SystemClock.elapsedRealtimeNanos()-300000000000L));
        ui(()->{manager.setTestProviderLocation(LocationManager.GPS_PROVIDER,stale);maps.beginLocation();check(maps.locationProviders.contains(LocationManager.GPS_PROVIDER),"Precise lookup actually subscribes to GPS");check(maps.locating,"Recent cache does not prematurely finish precise search");check(maps.lat!=1&&maps.lon!=2,"Stale accurate cache cannot move current pin");});
        ui(()->manager.setTestProviderLocation(LocationManager.NETWORK_PROVIDER,fix(LocationManager.NETWORK_PROVIDER,40.6,-74.3,1200)));await(()->maps.lastFix!=null&&maps.lastFix.getAccuracy()>50,"Rough current fix is shown while GPS improves");check(maps.locating,"Rough first result does not finish a precise search");
        final LocationListener[] old={null};ui(()->{old[0]=maps.locationListener;manager.setTestProviderLocation(LocationManager.GPS_PROVIDER,fix(LocationManager.GPS_PROVIDER,40.700123,-74.012345,4));});await(()->!maps.locating&&Math.abs(maps.lat-40.700123)<.000001&&Math.abs(maps.lon+74.012345)<.000001,"Actual fresh GPS callback precisely centers the map");ui(()->{check(maps.zoom==17&&maps.locationStatus.getText().toString().contains("±4 m"),"Precise fix zoom and estimated accuracy are visible");check(maps.locationListener==null&&maps.locationTimeout==null&&maps.locationProviders.isEmpty(),"Successful fix removes all subscriptions and timeout");old[0].onLocationChanged(fix(LocationManager.GPS_PROVIDER,1,2,1));check(maps.lat==40.700123,"Late callback cannot move a completed fix");});shot("eight-location-precise");
        ui(()->{maps.beginLocation();check(maps.locating,"Another tap actively refreshes instead of accepting only cache");old[0]=maps.locationListener;home.open("@start");check(!maps.locating&&maps.locationListener==null&&maps.locationProviders.isEmpty(),"Hidden Maps cancels live location requests");old[0].onLocationChanged(fix(LocationManager.GPS_PROVIDER,3,4,1));check(maps.lat==40.700123,"Late hidden callback cannot move map");home.openEightTile("@maps");check(!maps.locating,"Returning to Maps does not restart tracking");maps.beginLocation();maps.finishLocation(true);check(!maps.locating&&maps.locationStatus.getText().toString().contains("Best available"),"Timeout path keeps and labels best available fix");});
        shell("cmd location set-location-enabled false");ui(()->{maps.beginLocation();check(!maps.locating&&maps.locationStatus.getText().toString().contains("location is off"),"Device location off has a clear recovery route");check(maps.accuracyDialog!=null&&maps.accuracyDialog.isShowing(),"Device location settings button is offered");maps.accuracyDialog.dismiss();});shell("cmd location set-location-enabled true");
        result.putString("stream","PASS: real Android permission denial and recovery; "+choice+"; approximate provider callbacks remain usable; actual GPS subscription and fresh 4m fixture callback center/zoom the map; stale accurate cache and rough first fix do not prematurely complete; estimated accuracy survives map-load status; completion, hidden Maps, late callbacks and timeout cleanup; device-location-off settings recovery. Test providers only; no physical GPS accuracy claim.\n");passed=true;
    }catch(Throwable failure){try{recordTree("eight-location-failure-tree.txt");shot("eight-location-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(failure));}finally{try{if(home!=null)ui(()->{if(maps!=null)maps.stopLocation();if(manager!=null)for(String p:mocks)try{manager.removeTestProvider(p);}catch(RuntimeException ignored){}});shell("cmd location set-location-enabled true");shell("appops set "+getTargetContext().getPackageName()+" android:mock_location default");}catch(Exception ignored){}}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
    Location fix(String provider,double lat,double lon,float accuracy){Location l=new Location(provider);l.setLatitude(lat);l.setLongitude(lon);l.setAccuracy(accuracy);l.setTime(System.currentTimeMillis());l.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());return l;}
    AccessibilityNodeInfo node(String id,String label){AccessibilityNodeInfo r=getUiAutomation().getRootInActiveWindow();if(r==null)return null;ArrayDeque<AccessibilityNodeInfo> q=new ArrayDeque<>();q.add(r);while(!q.isEmpty()){AccessibilityNodeInfo n=q.remove();String view=String.valueOf(n.getViewIdResourceName()),text=String.valueOf(n.getText());if(view.endsWith("/"+id)||text.equalsIgnoreCase(label))return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo c=n.getChild(i);if(c!=null)q.add(c);}}return null;}
    void awaitNode(String id,String label)throws Exception{await(()->node(id,label)!=null,"Permission action appears: "+label);}
    void tapSystem(String id,String label)throws Exception{AccessibilityNodeInfo n=node(id,label);check(n!=null,"System action "+label);Rect b=new Rect();n.getBoundsInScreen(b);long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,b.centerX(),b.centerY(),0),up=MotionEvent.obtain(now,now+80,MotionEvent.ACTION_UP,b.centerX(),b.centerY(),0);down.setSource(InputDevice.SOURCE_TOUCHSCREEN);up.setSource(InputDevice.SOURCE_TOUCHSCREEN);if(!n.performAction(AccessibilityNodeInfo.ACTION_CLICK)){check(getUiAutomation().injectInputEvent(down,true)&&getUiAutomation().injectInputEvent(up,true),"System tap injected "+label);}down.recycle();up.recycle();SystemClock.sleep(350);waitForIdleSync();}
    void recordTree(String name)throws Exception{AccessibilityNodeInfo r=getUiAutomation().getRootInActiveWindow();StringBuilder out=new StringBuilder();tree(r,out);try(OutputStream f=new FileOutputStream(new File(getTargetContext().getFilesDir(),name))){f.write(out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}}
    void tree(AccessibilityNodeInfo n,StringBuilder out){if(n==null)return;out.append(n.getViewIdResourceName()).append(" | ").append(n.getText()).append(" | ").append(n.getContentDescription()).append('\n');for(int i=0;i<n.getChildCount();i++)tree(n.getChild(i),out);}
    interface Condition{boolean ready()throws Exception;}void await(Condition c,String label)throws Exception{long end=SystemClock.uptimeMillis()+18000;while(SystemClock.uptimeMillis()<end){waitForIdleSync();if(c.ready())return;SystemClock.sleep(100);}throw new AssertionError(label);}
    void ui(Runnable action)throws Exception{FutureTask<Void> t=new FutureTask<>(action,null);home.runOnUiThread(t);t.get(20,TimeUnit.SECONDS);waitForIdleSync();}
    String shell(String command)throws Exception{try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand(command));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];for(int n;(n=in.read(b))!=-1;)out.write(b,0,n);return out.toString("UTF-8");}}
    void check(boolean value,String label){if(!value)throw new AssertionError(label);}
    void shot(String name)throws Exception{Bitmap b=Bitmap.createBitmap(root.getWidth(),root.getHeight(),Bitmap.Config.ARGB_8888);ui(()->root.draw(new Canvas(b)));try(OutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
}
